// Read directly from the source nodes so the logic stays dynamic
const employees = $items("Fetch Employee Data").map(item => item.json);
const suppliers = $items("Fetch Supplier Data").map(item => item.json);

const results = [];
const seenPairs = new Set();

// ---------- Helpers ----------
function normalizeText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizePhone(value) {
  return String(value ?? '').replace(/\D/g, '');
}

function normalizeEmail(value) {
  return String(value ?? '').toLowerCase().trim();
}

function getLastName(fullName) {
  const parts = normalizeText(fullName).split(' ').filter(Boolean);
  return parts.length ? parts[parts.length - 1] : '';
}

function safeNumber(value) {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function getCity(address) {
  const text = normalizeText(address);
  if (!text) return '';
  return text.split(',')[0].trim();
}

// ---------- Matching ----------
for (const emp of employees) {
  const empId = String(emp.EmployeeID ?? '').trim();
  const empName = normalizeText(emp.EmployeeName);
  const empEmail = normalizeEmail(emp.EmployeeEmail);
  const empPhone = normalizePhone(emp.EmployeePhone);
  const empAddress = normalizeText(emp.EmployeeAddress);
  const empCity = getCity(emp.EmployeeAddress);
  const empLastName = getLastName(emp.EmployeeName);

  for (const sup of suppliers) {
    const supId = String(sup.SupplierID ?? '').trim();
    const pairKey = `${empId}__${supId}`;
    if (seenPairs.has(pairKey)) continue;
    seenPairs.add(pairKey);

    let score = 0;
    const reasons = [];
    const matchDetails = [];

    const ownerName = normalizeText(sup.OwnerName);
    const supEmail = normalizeEmail(sup.SupplierEmail);
    const supPhone = normalizePhone(sup.SupplierPhone);
    const supAddress = normalizeText(sup.SupplierAddress);
    const supCity = getCity(sup.SupplierAddress);
    const supLastName = getLastName(sup.OwnerName);

    const txCount = safeNumber(sup.TransactionCount);
    const totalSpend = safeNumber(sup.TotalSpend);

    // 1. Strong direct signals
    if (empName && ownerName && empName === ownerName) {
      score += 50;
      reasons.push('Employee full name matches supplier owner name');
      matchDetails.push('full_name_exact');
    }

    if (empEmail && supEmail && empEmail === supEmail) {
      score += 40;
      reasons.push('Employee email matches supplier email');
      matchDetails.push('email_exact');
    }

    if (empPhone && supPhone && empPhone === supPhone) {
      score += 30;
      reasons.push('Employee phone matches supplier phone');
      matchDetails.push('phone_exact');
    }

    if (empAddress && supAddress && empAddress === supAddress) {
      score += 25;
      reasons.push('Employee address matches supplier address');
      matchDetails.push('address_exact');
    }

    // 2. Medium / indirect signals
    if (empLastName && supLastName && empLastName === supLastName && empName !== ownerName) {
      score += 15;
      reasons.push('Employee last name matches supplier owner last name');
      matchDetails.push('last_name_match');
    }

    if (empCity && supCity && empCity === supCity && empAddress !== supAddress) {
      score += 10;
      reasons.push('Employee city matches supplier city');
      matchDetails.push('city_match');
    }

    // 3. Transaction risk signals
    if (txCount > 10 && totalSpend > 50000) {
      score += 15;
      reasons.push('Supplier has unusually high transaction activity');
      matchDetails.push('high_transaction_activity');
    } else if (txCount >= 5 && totalSpend >= 20000) {
      score += 5;
      reasons.push('Supplier has moderate transaction activity');
      matchDetails.push('moderate_transaction_activity');
    }

    // 4. Decide risk level
    let riskLevel = 'Low';
    if (score >= 70) {
      riskLevel = 'High';
    } else if (score >= 40) {
      riskLevel = 'Medium';
    } else if (score >= 30) {
      riskLevel = 'Low Review';
    }

    // 5. Output only cases worth reviewing
    // Keep 30+ so medium and near-medium cases are visible for analysis
    if (score >= 30) {
      results.push({
        json: {
          Date: new Date().toISOString().split('T')[0],
          EmployeeID: emp.EmployeeID ?? '',
          EmployeeName: emp.EmployeeName ?? '',
          EmployeeEmail: emp.EmployeeEmail ?? '',
          EmployeePhone: emp.EmployeePhone ?? '',
          EmployeeAddress: emp.EmployeeAddress ?? '',
          Department: emp.Department ?? '',
          SupplierID: sup.SupplierID ?? '',
          SupplierName: sup.SupplierName ?? '',
          OwnerName: sup.OwnerName ?? '',
          SupplierEmail: sup.SupplierEmail ?? '',
          SupplierPhone: sup.SupplierPhone ?? '',
          SupplierAddress: sup.SupplierAddress ?? '',
          TransactionCount: txCount,
          TotalSpend: totalSpend,
          RiskScore: score,
          RiskLevel: riskLevel,
          Reasons: reasons.join('; '),
          MatchDetails: matchDetails.join(', '),
          Status: 'Open'
        }
      });
    }
  }
}

// Optional: sort highest risk first
results.sort((a, b) => b.json.RiskScore - a.json.RiskScore);

return results;

